cat << 'EOF' > parse.py
import json, glob

known = {}
for f in glob.glob("shared/submissions/*.json"):
    with open(f) as fp:
        try:
            data = json.load(fp)
            if "feedback" in data:
                fb = data["feedback"]
                if "next_position" in fb:
                    pos = fb["next_position"]
                    val = fb["next_value"]
                    known[pos] = val
        except:
            pass
print(known)
EOF
